package com.agroconnect.service;
import com.agroconnect.api.dto.ApiDtos.*;import com.agroconnect.domain.*;import com.agroconnect.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service @RequiredArgsConstructor
public class FarmerCommunityService {
 private final FarmerCommunityGroupRepository groups;private final FarmerCommunityMemberRepository members;private final FarmerCommunityMessageRepository messages;
 @Transactional(readOnly=true) public List<CommunityGroupResponse> list(User user){requireFarmer(user);return groups.findByActiveTrueOrderByNameAsc().stream().map(g->groupResponse(g,user)).toList();}
 @Transactional(readOnly=true) public List<CommunityGroupResponse> adminList(){return groups.findByActiveTrueOrderByNameAsc().stream().map(g->new CommunityGroupResponse(g.getId(),g.getName(),g.getDescription(),g.getLocality(),g.getCreatedBy()==null?"AgroConnect":g.getCreatedBy().getFullName(),members.countByGroup_Id(g.getId()),false,g.getCreatedAt())).toList();}
 @Transactional public CommunityGroupResponse create(User user,CommunityGroupCreateRequest req){requireFarmer(user);FarmerCommunityGroup g=new FarmerCommunityGroup();g.setName(req.name().trim());g.setDescription(req.description().trim());g.setLocality(req.locality()==null?null:req.locality().trim());g.setCreatedBy(user);g=groups.save(g);joinEntity(g,user);return groupResponse(g,user);}
 @Transactional public CommunityGroupResponse join(User user,UUID id){requireFarmer(user);FarmerCommunityGroup g=find(id);if(!members.existsByGroup_IdAndUser_Id(id,user.getId()))joinEntity(g,user);return groupResponse(g,user);}
 @Transactional public void leave(User user,UUID id){FarmerCommunityGroup g=find(id);FarmerCommunityMember m=members.findByGroup_IdAndUser_Id(id,user.getId()).orElseThrow(()->new BadRequestException("You are not a member of this group"));if(g.getCreatedBy()!=null&&g.getCreatedBy().getId().equals(user.getId()))throw new BadRequestException("Group creator must transfer or close the group before leaving");members.delete(m);}
 @Transactional(readOnly=true) public List<CommunityMemberResponse> memberList(User user,UUID id){FarmerCommunityGroup g=find(id);requireMember(user,g);return members.findByGroup_IdOrderByJoinedAtAsc(id).stream().map(m->new CommunityMemberResponse(m.getUser().getId(),m.getUser().getFullName(),m.getUser().getVillage(),m.getUser().getDistrict(),m.getJoinedAt())).toList();}
 @Transactional(readOnly=true) public List<CommunityMessageResponse> messageList(User user,UUID id){FarmerCommunityGroup g=find(id);requireMember(user,g);List<FarmerCommunityMessage> rows=messages.findTop100ByGroup_IdOrderByCreatedAtDesc(id);Collections.reverse(rows);return rows.stream().map(this::response).toList();}
 @Transactional public CommunityMessageResponse send(User user,UUID id,CommunityMessageRequest req){requireFarmer(user);FarmerCommunityGroup g=find(id);requireMember(user,g);FarmerCommunityMessage m=new FarmerCommunityMessage();m.setGroup(g);m.setSender(user);m.setMessage(req.message().trim());return response(messages.save(m));}
 @Transactional public void moderate(UUID id){FarmerCommunityGroup g=find(id);g.setActive(false);}
 private FarmerCommunityGroup find(UUID id){return groups.findById(id).filter(FarmerCommunityGroup::isActive).orElseThrow(()->new NotFoundException("Community group not found"));}
 private void joinEntity(FarmerCommunityGroup g,User u){FarmerCommunityMember m=new FarmerCommunityMember();m.setGroup(g);m.setUser(u);members.save(m);}
 private CommunityGroupResponse groupResponse(FarmerCommunityGroup g,User u){return new CommunityGroupResponse(g.getId(),g.getName(),g.getDescription(),g.getLocality(),g.getCreatedBy()==null?"AgroConnect":g.getCreatedBy().getFullName(),members.countByGroup_Id(g.getId()),members.existsByGroup_IdAndUser_Id(g.getId(),u.getId()),g.getCreatedAt());}
 private CommunityMessageResponse response(FarmerCommunityMessage m){return new CommunityMessageResponse(m.getId(),m.getSender().getId(),m.getSender().getFullName(),m.getSender().getVillage(),m.getMessage(),m.getCreatedAt());}
 private void requireFarmer(User u){if(u.getRoles()==null||!u.getRoles().contains(Role.FARMER))throw new AccessDeniedException("A farmer account is required");}
 private void requireMember(User u,FarmerCommunityGroup g){if(!members.existsByGroup_IdAndUser_Id(g.getId(),u.getId()))throw new AccessDeniedException("Join this group to view its members and messages");}
}
